func TestScannerStubBenchModeZeroAlloc(t *testing.T) {
	s := scannertest.NewScannerStub(nil, scannertest.ScannerStubBenchMode())
	s.OnCount.Returns(0, nil)
	s.OnKeys.Returns(nil)
	s.OnScan.Returns(nil)

	t.Run("Count", func(t *testing.T) {
		const iterations = 100
		avgAllocs := testing.AllocsPerRun(iterations, func() {
			_, _ = s.Count(t.Context())
		})
		testkit.Equal(t, int(avgAllocs), 0, "Count in BenchMode must be 0 alloc")
	})

	t.Run("Keys", func(t *testing.T) {
		const iterations = 100
		avgAllocs := testing.AllocsPerRun(iterations, func() {
			_ = s.Keys(t.Context())
		})
		testkit.Equal(t, int(avgAllocs), 0, "Keys in BenchMode must be 0 alloc")
	})

	t.Run("Scan", func(t *testing.T) {
		const iterations = 100
		avgAllocs := testing.AllocsPerRun(iterations, func() {
			_ = s.Scan(t.Context(), "")
		})
		testkit.Equal(t, int(avgAllocs), 0, "Scan in BenchMode must be 0 alloc")
	})

}
